using System.IO;

namespace Azure.Provisioning.Generator.Model;

public abstract partial class Specification
{
    private void GenerateResourceReference() =>
        SaveFile(
            Path.Combine("Internal", "ProvisioningResourceReference.cs"),
            $$"""
            // Copyright (c) Microsoft Corporation. All rights reserved.
            // Licensed under the MIT License.

            // <auto-generated/>

            #nullable enable

            using Azure.Provisioning.Expressions;
            using Azure.Provisioning.Primitives;

            namespace {{LibraryNamespace}};

            internal sealed class ProvisioningResourceReference<T>(BicepValue<string> reference)
                where T : ProvisionableResource
            {
                private readonly BicepValue<string> _reference = reference;
                private T? _value;

                internal T? Value
                {
                    get => _value;
                    set
                    {
                        _value = value;
                        if (value is null)
                        {
                            _reference.ClearValue();
                        }
                        else
                        {
                            ((IBicepValue)_reference).Expression = BicepSyntax.Var(value.BicepIdentifier);
                        }
                    }
                }
            }

            """);
}
